PRAGMA application_id=1414745415;
PRAGMA user_version=74;
BEGIN TRANSACTION;
CREATE TABLE adoption_receipts (
        action_id TEXT PRIMARY KEY NOT NULL, attempt_id TEXT NOT NULL, unit_id TEXT NOT NULL,
        receipt BLOB NOT NULL CHECK(length(receipt) BETWEEN 1 AND 1048576), digest TEXT NOT NULL CHECK(length(digest) = 64),
        UNIQUE(attempt_id,unit_id),
        FOREIGN KEY(action_id,attempt_id,unit_id) REFERENCES execution_actions(action_id,attempt_id,unit_id));
INSERT INTO "adoption_receipts" VALUES('253c63f7-190f-4a0d-8c4d-88cc1081ff7a','dac039c8-e0a2-4194-aeb7-1bd47237ba8c','0f9bafcc-2485-47c3-89ea-5357d5bcb9fd',X'','5802fc605f6f9dc8d418b082756a1ce857ff5a197669171b164759d62dd70bd7');
CREATE TABLE application_actions (action_id TEXT PRIMARY KEY NOT NULL, plan_id TEXT NOT NULL REFERENCES application_plans(plan_id), request BLOB NOT NULL CHECK(length(request) BETWEEN 1 AND 1048576), request_digest TEXT NOT NULL CHECK(length(request_digest)=64), receipt BLOB NOT NULL CHECK(length(receipt) BETWEEN 1 AND 1048576), receipt_digest TEXT NOT NULL CHECK(length(receipt_digest)=64));
CREATE TABLE application_conversation_actions (action_id TEXT PRIMARY KEY NOT NULL, conversation_id TEXT NOT NULL REFERENCES application_conversations(conversation_id), request BLOB NOT NULL CHECK(length(request) BETWEEN 1 AND 65536), request_digest TEXT NOT NULL CHECK(length(request_digest)=64), receipt BLOB NOT NULL CHECK(length(receipt) BETWEEN 1 AND 65536), receipt_digest TEXT NOT NULL CHECK(length(receipt_digest)=64));
CREATE TABLE application_conversation_messages (message_id TEXT PRIMARY KEY NOT NULL, conversation_id TEXT NOT NULL REFERENCES application_conversations(conversation_id), ordinal INTEGER NOT NULL CHECK(ordinal>0), record BLOB NOT NULL CHECK(length(record) BETWEEN 1 AND 65536), digest TEXT NOT NULL CHECK(length(digest)=64), UNIQUE(conversation_id,ordinal));
CREATE TABLE application_conversation_planning_attempts (attempt_id TEXT PRIMARY KEY NOT NULL REFERENCES execution_attempts(attempt_id), conversation_id TEXT NOT NULL REFERENCES application_conversations(conversation_id), sequence INTEGER NOT NULL UNIQUE CHECK(sequence>0), UNIQUE(conversation_id,sequence));
CREATE TABLE application_conversation_proposals (revision_id TEXT PRIMARY KEY NOT NULL, proposal_id TEXT NOT NULL, conversation_id TEXT NOT NULL REFERENCES application_conversations(conversation_id), revision INTEGER NOT NULL CHECK(revision>0), ordinal INTEGER NOT NULL CHECK(ordinal>0), previous_revision_id TEXT UNIQUE REFERENCES application_conversation_proposals(revision_id), record BLOB NOT NULL CHECK(length(record) BETWEEN 1 AND 65536), digest TEXT NOT NULL CHECK(length(digest)=64), UNIQUE(proposal_id,revision), UNIQUE(conversation_id,ordinal));
CREATE TABLE application_conversation_work_plans (plan_id TEXT PRIMARY KEY NOT NULL REFERENCES application_plans(plan_id), action_id TEXT NOT NULL UNIQUE REFERENCES application_actions(action_id), revision_id TEXT NOT NULL REFERENCES application_conversation_proposals(revision_id), conversation_id TEXT NOT NULL REFERENCES application_conversations(conversation_id), ordinal INTEGER NOT NULL CHECK(ordinal>0), request BLOB NOT NULL CHECK(length(request) BETWEEN 1 AND 4194304), request_digest TEXT NOT NULL CHECK(length(request_digest)=64), record BLOB NOT NULL CHECK(length(record) BETWEEN 1 AND 4096), digest TEXT NOT NULL CHECK(length(digest)=64), UNIQUE(conversation_id,ordinal));
CREATE TABLE application_conversations (conversation_id TEXT PRIMARY KEY NOT NULL, ordinal INTEGER NOT NULL UNIQUE CHECK(ordinal>0), record BLOB NOT NULL CHECK(length(record) BETWEEN 1 AND 4096), digest TEXT NOT NULL CHECK(length(digest)=64));
CREATE TABLE application_executions (attempt_id TEXT PRIMARY KEY NOT NULL REFERENCES execution_attempts(attempt_id), plan_id TEXT NOT NULL REFERENCES application_plans(plan_id), generation INTEGER NOT NULL CHECK(generation>0), kind TEXT NOT NULL CHECK(kind IN ('model','tool')), delegation BLOB CHECK(delegation IS NULL OR length(delegation) BETWEEN 1 AND 8192), root_task TEXT NOT NULL REFERENCES execution_tasks(task_id), CHECK(kind='model' OR (kind='tool' AND delegation IS NOT NULL)));
CREATE TABLE application_plans (plan_id TEXT PRIMARY KEY NOT NULL, plan BLOB NOT NULL CHECK(length(plan) BETWEEN 1 AND 1048576), digest TEXT NOT NULL CHECK(length(digest)=64), generation INTEGER NOT NULL CHECK(generation>0), state TEXT NOT NULL CHECK(state IN ('active','paused','stopped','taken-over')), effects BLOB NOT NULL CHECK(length(effects) BETWEEN 1 AND 1024), expires_at INTEGER NOT NULL CHECK(expires_at>0), cancellation_revision INTEGER NOT NULL CHECK(cancellation_revision>=0));
CREATE TABLE application_protection_actions (action_id TEXT PRIMARY KEY NOT NULL, request BLOB NOT NULL CHECK(length(request) BETWEEN 1 AND 1048576), digest TEXT NOT NULL CHECK(length(digest)=64), receipt BLOB NOT NULL CHECK(length(receipt) BETWEEN 1 AND 1048576), receipt_digest TEXT NOT NULL CHECK(length(receipt_digest)=64));
CREATE TABLE application_protections (unit_id TEXT NOT NULL REFERENCES source_units(unit_id), locale TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), protected INTEGER NOT NULL CHECK(protected IN (0,1)), PRIMARY KEY(unit_id,locale));
INSERT INTO "application_protections" VALUES('b92f7f49-b6c3-4353-b2ff-c2f18fa4b9a5','zh-CN',1,1);
CREATE TABLE application_selection_actions (action_id TEXT PRIMARY KEY NOT NULL, plan_id TEXT NOT NULL REFERENCES application_plans(plan_id), revision_id TEXT NOT NULL REFERENCES translation_revisions(revision_id), selection_id TEXT REFERENCES translation_selections(event_id), request BLOB NOT NULL CHECK(length(request) BETWEEN 1 AND 1048576), request_digest TEXT NOT NULL CHECK(length(request_digest)=64), receipt BLOB NOT NULL CHECK(length(receipt) BETWEEN 1 AND 1048576), receipt_digest TEXT NOT NULL CHECK(length(receipt_digest)=64));
CREATE TABLE application_service_calls (child_attempt TEXT PRIMARY KEY NOT NULL REFERENCES execution_attempts(attempt_id), outer_attempt TEXT NOT NULL REFERENCES execution_attempts(attempt_id), outer_item TEXT NOT NULL, outer_dispatch TEXT NOT NULL, grant_id TEXT NOT NULL REFERENCES plugin_execution_grants(grant_id), handle_id TEXT NOT NULL CHECK(length(handle_id) BETWEEN 1 AND 128), call_id TEXT NOT NULL CHECK(length(call_id) BETWEEN 1 AND 128), origin BLOB NOT NULL CHECK(length(origin) BETWEEN 1 AND 4194304), origin_digest TEXT NOT NULL CHECK(length(origin_digest)=64), call BLOB NOT NULL CHECK(length(call) BETWEEN 1 AND 4194304), call_digest TEXT NOT NULL CHECK(length(call_digest)=64), UNIQUE(outer_attempt,outer_item,outer_dispatch,handle_id,call_id));
CREATE TABLE application_team_consumptions (message_id TEXT PRIMARY KEY NOT NULL REFERENCES application_team_messages(message_id), task_id TEXT NOT NULL REFERENCES execution_tasks(task_id), request_id TEXT NOT NULL REFERENCES execution_provider_requests(request_id));
CREATE TABLE application_team_members (member_id TEXT PRIMARY KEY NOT NULL, plan_id TEXT NOT NULL REFERENCES application_plans(plan_id), task_id TEXT UNIQUE REFERENCES execution_tasks(task_id), UNIQUE(plan_id,member_id));
CREATE TABLE application_team_messages (message_id TEXT PRIMARY KEY NOT NULL, plan_id TEXT NOT NULL REFERENCES application_plans(plan_id), sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 256), recipient TEXT NOT NULL REFERENCES application_team_members(member_id), record BLOB NOT NULL CHECK(length(record) BETWEEN 1 AND 32768), digest TEXT NOT NULL CHECK(length(digest)=64), UNIQUE(plan_id,sequence));
CREATE TABLE application_team_posts (post_id TEXT PRIMARY KEY NOT NULL, plan_id TEXT NOT NULL REFERENCES application_plans(plan_id), sequence INTEGER NOT NULL CHECK(sequence>0 AND sequence<=128), reply_to TEXT REFERENCES application_team_posts(post_id), supersedes TEXT UNIQUE REFERENCES application_team_posts(post_id), record BLOB NOT NULL CHECK(length(record) BETWEEN 1 AND 32768), digest TEXT NOT NULL CHECK(length(digest)=64), UNIQUE(plan_id,sequence));
CREATE TABLE application_team_roles (version_id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES application_team_members(member_id), ordinal INTEGER NOT NULL CHECK(ordinal>0 AND ordinal<=16), predecessor TEXT UNIQUE REFERENCES application_team_roles(version_id), record BLOB NOT NULL CHECK(length(record) BETWEEN 1 AND 32768), digest TEXT NOT NULL CHECK(length(digest)=64), UNIQUE(member_id,ordinal), UNIQUE(member_id,version_id));
CREATE TABLE application_team_work (intent_id TEXT PRIMARY KEY NOT NULL, plan_id TEXT NOT NULL REFERENCES application_plans(plan_id), sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 300), member_id TEXT NOT NULL REFERENCES application_team_members(member_id), role_version TEXT NOT NULL REFERENCES application_team_roles(version_id), task_id TEXT NOT NULL UNIQUE REFERENCES execution_tasks(task_id), attempt_id TEXT NOT NULL UNIQUE REFERENCES execution_attempts(attempt_id), record BLOB NOT NULL CHECK(length(record) BETWEEN 1 AND 65536), digest TEXT NOT NULL CHECK(length(digest)=64), deadline_at_ms INTEGER NOT NULL CHECK(deadline_at_ms>0), UNIQUE(plan_id,sequence));
CREATE TABLE arena_comparisons (comparison_id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL, unit_id TEXT NOT NULL REFERENCES source_units(unit_id), locale TEXT NOT NULL, blind INTEGER NOT NULL CHECK(blind IN (0,1)), request_digest TEXT NOT NULL CHECK(length(request_digest)=64));
CREATE TABLE arena_entries (comparison_id TEXT NOT NULL REFERENCES arena_comparisons(comparison_id), ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 3), revision_id TEXT NOT NULL REFERENCES translation_revisions(revision_id), PRIMARY KEY(comparison_id,ordinal), UNIQUE(comparison_id,revision_id));
CREATE TABLE arena_reveals (comparison_id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL, action_id TEXT NOT NULL UNIQUE, request_digest TEXT NOT NULL CHECK(length(request_digest)=64));
CREATE TABLE content_scope (
        row_id INTEGER PRIMARY KEY CHECK(row_id=1), revision INTEGER NOT NULL CHECK(revision>0),
        current_snapshot TEXT REFERENCES source_snapshots(snapshot_id));
INSERT INTO "content_scope" VALUES(1,2,'e55a0d0b-14d2-4cf1-a6f5-c316a60b801b');
CREATE TABLE context_captures (
        capture_id TEXT PRIMARY KEY NOT NULL,
        project_id TEXT NOT NULL,
        unit_id TEXT NOT NULL REFERENCES source_units(unit_id),
        locale TEXT NOT NULL,
        source_revision_id TEXT NOT NULL,
        input_json TEXT NOT NULL CHECK(length(CAST(input_json AS BLOB))<=32768),
        action_id TEXT NOT NULL UNIQUE,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64));
CREATE TABLE context_current (
        unit_id TEXT REFERENCES source_units(unit_id),
        locale TEXT NOT NULL,
        revision_id TEXT NOT NULL REFERENCES context_revisions(revision_id),
        context_id TEXT UNIQUE,
        UNIQUE(unit_id,locale),
        CHECK((unit_id IS NULL)<>(context_id IS NULL)));
CREATE TABLE context_fact_decisions (action_id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL, unit_id TEXT NOT NULL REFERENCES source_units(unit_id), locale TEXT NOT NULL, source_snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id), source_revision_id TEXT NOT NULL REFERENCES source_revisions(revision_id), block_index INTEGER NOT NULL CHECK(block_index>=0), fact_id TEXT NOT NULL, previous_action_id TEXT REFERENCES context_fact_decisions(action_id), request BLOB NOT NULL CHECK(length(request) BETWEEN 1 AND 131072), request_digest TEXT NOT NULL CHECK(length(request_digest)=64));
CREATE TABLE context_revisions (
        revision_id TEXT PRIMARY KEY NOT NULL,
        project_id TEXT NOT NULL,
        unit_id TEXT REFERENCES source_units(unit_id),
        locale TEXT NOT NULL,
        text TEXT NOT NULL CHECK(length(CAST(text AS BLOB))<=16384),
        reason TEXT NOT NULL,
        previous_revision_id TEXT REFERENCES context_revisions(revision_id),
        action_id TEXT NOT NULL UNIQUE,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        context_id TEXT,
        subject_id TEXT,
        resource_kind TEXT,
        record_json TEXT CHECK(record_json IS NULL OR length(CAST(record_json AS BLOB))<=65536),
        CHECK((unit_id IS NOT NULL AND context_id IS NULL AND subject_id IS NULL AND resource_kind IS NULL AND record_json IS NULL)
           OR (unit_id IS NULL AND context_id IS NOT NULL AND subject_id IS NOT NULL AND resource_kind IN ('character','style','background') AND record_json IS NOT NULL)));
CREATE TABLE context_strategy_actions (action_id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL, kind TEXT NOT NULL, request BLOB NOT NULL, request_digest TEXT NOT NULL CHECK(length(request_digest)=64), receipt BLOB);
CREATE TABLE context_strategy_facts (kind TEXT NOT NULL, fact_id TEXT NOT NULL, project_id TEXT NOT NULL, payload BLOB NOT NULL, digest TEXT NOT NULL CHECK(length(digest)=64), locale TEXT, association_id TEXT, member_id TEXT, PRIMARY KEY(kind,fact_id));
CREATE TABLE execution_actions (
        action_id TEXT PRIMARY KEY NOT NULL, attempt_id TEXT NOT NULL REFERENCES execution_attempts(attempt_id),
        unit_id TEXT NOT NULL, request BLOB NOT NULL CHECK(length(request) BETWEEN 1 AND 1048576),
        digest TEXT NOT NULL CHECK(length(digest) = 64), UNIQUE(action_id,attempt_id,unit_id));
INSERT INTO "execution_actions" VALUES('253c63f7-190f-4a0d-8c4d-88cc1081ff7a','dac039c8-e0a2-4194-aeb7-1bd47237ba8c','0f9bafcc-2485-47c3-89ea-5357d5bcb9fd',X'','284cac351cb6a8bdd55a243aa174d610a87d4e214f16999457bc9af8d997ae3b');
CREATE TABLE execution_attempts (
        attempt_id TEXT PRIMARY KEY NOT NULL, task_id TEXT NOT NULL, project_id TEXT NOT NULL,
        previous_attempt_id TEXT REFERENCES execution_attempts(attempt_id),
        input BLOB NOT NULL CHECK(typeof(input)='blob' AND length(input) BETWEEN 1 AND 18432), digest TEXT NOT NULL CHECK(length(digest) = 64),
        cancellation_revision INTEGER NOT NULL CHECK(cancellation_revision >= 0),
        sequence INTEGER NOT NULL UNIQUE CHECK(sequence > 0),
        FOREIGN KEY(task_id, project_id) REFERENCES execution_tasks(task_id, project_id));
INSERT INTO "execution_attempts" VALUES('dac039c8-e0a2-4194-aeb7-1bd47237ba8c','cd6f6b48-396e-4983-9c99-ad17468e214d','9f32dc2b-b253-4ecc-a410-8bd78d9b8e29',NULL,X'7B22666F726D6174223A312C227261774279746573223A313630342C226368756E6B73223A5B2232616136643261613462343936623062326230343530656166373962383430323633336638643232373764336436363238633663323164346161343463393530225D7D','2aa6d2aa4b496b0b2b0450eaf79b8402633f8d2277d3d6628c6c21d4aa44c950',0,1);
CREATE TABLE execution_budget_ancestry (task_id TEXT NOT NULL REFERENCES execution_budgets(task_id), ancestor_id TEXT NOT NULL REFERENCES execution_budgets(task_id), PRIMARY KEY(task_id,ancestor_id));
CREATE TABLE execution_budgets (task_id TEXT PRIMARY KEY NOT NULL REFERENCES execution_tasks(task_id), parent_id TEXT REFERENCES execution_budgets(task_id), request_limit INTEGER NOT NULL CHECK(request_limit BETWEEN 1 AND 300), legacy_held INTEGER NOT NULL CHECK(legacy_held BETWEEN 0 AND request_limit), CHECK(task_id<>parent_id));
CREATE TABLE execution_cancellations (
        request_id TEXT PRIMARY KEY NOT NULL, task_id TEXT NOT NULL REFERENCES execution_tasks(task_id),
        revision INTEGER NOT NULL CHECK(revision > 0), UNIQUE(task_id,revision));
CREATE TABLE execution_continuations (
        action_id TEXT PRIMARY KEY NOT NULL, source_attempt_id TEXT NOT NULL REFERENCES execution_attempts(attempt_id),
        unit_id TEXT NOT NULL, attempt_id TEXT NOT NULL UNIQUE REFERENCES execution_attempts(attempt_id),
        receipt BLOB NOT NULL CHECK(length(receipt) BETWEEN 1 AND 1048576),
        digest TEXT NOT NULL CHECK(length(digest) = 64));
CREATE TABLE execution_effects (attempt_id TEXT PRIMARY KEY NOT NULL REFERENCES execution_attempts(attempt_id), policy TEXT NOT NULL CHECK(policy IN ('read-only','idempotent-local-write','external-unknown')));
INSERT INTO "execution_effects" VALUES('dac039c8-e0a2-4194-aeb7-1bd47237ba8c','read-only');
CREATE TABLE execution_input_chunks (
    digest TEXT PRIMARY KEY NOT NULL CHECK(length(digest)=64),
    bytes BLOB NOT NULL CHECK(typeof(bytes)='blob' AND length(bytes) BETWEEN 1 AND 16384));
INSERT INTO "execution_input_chunks" VALUES('2aa6d2aa4b496b0b2b0450eaf79b8402633f8d2277d3d6628c6c21d4aa44c950',X'');
CREATE TABLE execution_items (
        attempt_id TEXT NOT NULL REFERENCES execution_attempts(attempt_id), item_id TEXT NOT NULL,
        execution TEXT NOT NULL CHECK(execution IN ('queued','dispatched','succeeded','failed','cancelled-before-dispatch','unknown')),
        validation TEXT NOT NULL CHECK(validation IN ('absent','pending','valid','invalid')),
        adoption TEXT NOT NULL CHECK(adoption IN ('unapplied','committed','conflict','rejected')),
        dispatch_token TEXT UNIQUE, current_result_id TEXT,
        retry_safe INTEGER NOT NULL CHECK(retry_safe IN (0,1)), diagnostic TEXT CHECK(length(diagnostic) <= 4096),
        PRIMARY KEY(attempt_id,item_id), UNIQUE(attempt_id,item_id,dispatch_token));
INSERT INTO "execution_items" VALUES('dac039c8-e0a2-4194-aeb7-1bd47237ba8c','adec7233-df2a-45fb-9cd4-63a649d1e65c','succeeded','valid','committed','5e5f047c-830e-4104-94e3-aa5ffbcf0e15','895992c3-fa84-44e9-8d40-9719bd76c0ca',0,NULL);
CREATE TABLE execution_provider_requests (request_id TEXT PRIMARY KEY NOT NULL, task_id TEXT NOT NULL REFERENCES execution_budgets(task_id), attempt_id TEXT NOT NULL, item_id TEXT NOT NULL, dispatch_token TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('unknown','response')), usage BLOB CHECK(usage IS NULL OR length(usage) BETWEEN 1 AND 1024), capture BLOB CHECK(capture IS NULL OR length(capture) BETWEEN 1 AND 131072), capture_digest TEXT CHECK(capture_digest IS NULL OR length(capture_digest)=64), CHECK((capture IS NULL)=(capture_digest IS NULL)), FOREIGN KEY(attempt_id,item_id,dispatch_token) REFERENCES execution_items(attempt_id,item_id,dispatch_token));
CREATE TABLE "execution_results" (
        result_id TEXT PRIMARY KEY NOT NULL, attempt_id TEXT NOT NULL, item_id TEXT NOT NULL, dispatch_token TEXT NOT NULL,
        bytes BLOB NOT NULL CHECK(length(bytes) BETWEEN 1 AND 8388608), digest TEXT NOT NULL CHECK(length(digest) = 64),
        FOREIGN KEY(attempt_id,item_id,dispatch_token) REFERENCES execution_items(attempt_id,item_id,dispatch_token));
INSERT INTO "execution_results" VALUES('895992c3-fa84-44e9-8d40-9719bd76c0ca','dac039c8-e0a2-4194-aeb7-1bd47237ba8c','adec7233-df2a-45fb-9cd4-63a649d1e65c','5e5f047c-830e-4104-94e3-aa5ffbcf0e15',X'','37ca7ac71447ff526942d815714512bbe2ae12babd4c226cff2171ddc5898910');
CREATE TABLE execution_tasks (
        task_id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL, operation TEXT NOT NULL,
        sequence INTEGER NOT NULL UNIQUE CHECK(sequence > 0), UNIQUE(task_id, project_id));
INSERT INTO "execution_tasks" VALUES('cd6f6b48-396e-4983-9c99-ad17468e214d','9f32dc2b-b253-4ecc-a410-8bd78d9b8e29','source-import',1);
CREATE TABLE mcp_query_actions (
        action_id TEXT PRIMARY KEY NOT NULL, attempt_id TEXT NOT NULL UNIQUE REFERENCES execution_attempts(attempt_id),
        input_digest TEXT NOT NULL CHECK(length(input_digest)=64));
CREATE TABLE plugin_execution_grants (grant_id TEXT PRIMARY KEY NOT NULL, attempt_id TEXT NOT NULL UNIQUE, task_id TEXT NOT NULL, input_digest TEXT NOT NULL CHECK(length(input_digest)=64), generation TEXT NOT NULL, expires_at_ms INTEGER NOT NULL CHECK(expires_at_ms>0), unsandboxed_execution INTEGER NOT NULL CHECK(unsandboxed_execution=1), application_execution INTEGER NOT NULL CHECK(application_execution IN (0,1)), revoked INTEGER NOT NULL CHECK(revoked IN (0,1)), delegation BLOB CHECK(delegation IS NULL OR length(delegation) BETWEEN 1 AND 8192));
CREATE TABLE plugin_validation_links (
        producer_result_id TEXT PRIMARY KEY NOT NULL REFERENCES execution_results(result_id),
        checker_result_id TEXT NOT NULL REFERENCES execution_results(result_id),
        valid INTEGER NOT NULL CHECK(valid IN (0,1)));
CREATE TABLE project_metadata (row_id INTEGER PRIMARY KEY CHECK (row_id = 1),project_id TEXT NOT NULL,display_name TEXT NOT NULL,source_locale TEXT NOT NULL,target_locales_json TEXT NOT NULL,metadata_revision INTEGER NOT NULL CHECK (metadata_revision > 0));
INSERT INTO "project_metadata" VALUES(1,'9f32dc2b-b253-4ecc-a410-8bd78d9b8e29','Supported text project','en','["zh-CN"]',1);
CREATE TABLE release_artifacts (
        release_id TEXT NOT NULL REFERENCES release_records(release_id),
        locale TEXT NOT NULL, artifact_id TEXT NOT NULL, role TEXT NOT NULL, file_name TEXT NOT NULL,
        bytes BLOB NOT NULL CHECK(length(bytes) BETWEEN 0 AND 2097152),
        sha256 TEXT NOT NULL CHECK(length(sha256)=64),
        validator_version TEXT NOT NULL, entry_count INTEGER NOT NULL CHECK(entry_count>0),
        PRIMARY KEY(release_id,locale,artifact_id), UNIQUE(release_id,file_name));
CREATE TABLE release_deliveries (
        delivery_id TEXT PRIMARY KEY NOT NULL, action_id TEXT NOT NULL UNIQUE,
        release_id TEXT NOT NULL REFERENCES release_records(release_id),
        directory TEXT NOT NULL, overwrite_conflicts INTEGER NOT NULL CHECK(overwrite_conflicts IN (0,1)),
        state TEXT NOT NULL CHECK(state IN ('pending','succeeded','partial','failed','unknown')),
        expected_json TEXT NOT NULL, results_json TEXT,
        created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE release_records (
        release_id TEXT PRIMARY KEY NOT NULL, action_id TEXT NOT NULL UNIQUE,
        project_id TEXT NOT NULL, attempt_id TEXT NOT NULL REFERENCES execution_attempts(attempt_id),
        manifest BLOB NOT NULL CHECK(length(manifest) BETWEEN 1 AND 4194304),
        manifest_digest TEXT NOT NULL CHECK(length(manifest_digest)=64),
        created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE resource_captures (
        capture_id TEXT PRIMARY KEY NOT NULL,
        project_id TEXT NOT NULL,
        capture_kind TEXT NOT NULL CHECK(capture_kind IN ('file','correction','mcp','conversation')),
        correction_key TEXT UNIQUE,
        resource_id TEXT,
        resource_revision TEXT,
        source_locale TEXT NOT NULL,
        target_locale TEXT NOT NULL,
        license TEXT,
        digest TEXT NOT NULL CHECK(length(digest)=64),
        bytes BLOB NOT NULL CHECK(length(bytes) BETWEEN 1 AND 262144),
        action_id TEXT NOT NULL UNIQUE,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        UNIQUE(project_id,resource_id,resource_revision),
        CHECK((capture_kind='file' AND correction_key IS NULL AND resource_id IS NOT NULL AND resource_revision IS NOT NULL AND license IS NOT NULL)
           OR (capture_kind='correction' AND correction_key IS NOT NULL AND length(correction_key)=64 AND resource_id IS NULL AND resource_revision IS NULL AND license IS NULL)
           OR (capture_kind IN ('mcp','conversation') AND correction_key IS NULL AND resource_id IS NULL AND resource_revision IS NULL AND license IS NULL)));
CREATE TABLE resource_changes (
        change_id TEXT PRIMARY KEY NOT NULL,
        project_id TEXT NOT NULL,
        kind TEXT NOT NULL CHECK(kind IN ('term','context','context-fact','context-resource')),
        locale TEXT NOT NULL,
        scope_unit_id TEXT REFERENCES source_units(unit_id),
        old_scope_unit_id TEXT REFERENCES source_units(unit_id),
        source_phrase TEXT,
        old_source_phrase TEXT,
        old_revision_id TEXT,
        new_revision_id TEXT NOT NULL,
        action_id TEXT NOT NULL UNIQUE,
        scope_json TEXT,
        old_scope_json TEXT);
CREATE TABLE resource_decisions (
        action_id TEXT PRIMARY KEY NOT NULL,
        project_id TEXT NOT NULL,
        capture_id TEXT NOT NULL REFERENCES resource_captures(capture_id),
        entry_id TEXT NOT NULL,
        decision TEXT NOT NULL CHECK(decision IN ('adopt','keep','ignore','override')),
        expected_revision_id TEXT,
        result_revision_id TEXT REFERENCES term_revisions(revision_id),
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        edited_target TEXT);
CREATE TABLE review_checks (
        run_id TEXT PRIMARY KEY NOT NULL,
        action_id TEXT NOT NULL UNIQUE,
        project_id TEXT NOT NULL,
        unit_id TEXT NOT NULL REFERENCES source_units(unit_id),
        locale TEXT NOT NULL,
        basis TEXT NOT NULL CHECK(length(basis)=64),
        basis_json TEXT NOT NULL,
        validator_version TEXT NOT NULL,
        rules_json TEXT NOT NULL,
        qa_basis TEXT CHECK(qa_basis IS NULL OR length(qa_basis)=64),
        evidence_json TEXT,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        purpose TEXT NOT NULL CHECK(purpose IN ('qa','ai-semantic')),
        created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
        CHECK((purpose='qa' AND (qa_basis IS NULL)=(evidence_json IS NULL)) OR
              (purpose='ai-semantic' AND qa_basis IS NULL AND evidence_json IS NOT NULL)));
CREATE TABLE review_decisions (
        decision_id TEXT PRIMARY KEY NOT NULL,
        action_id TEXT NOT NULL UNIQUE,
        project_id TEXT NOT NULL,
        unit_id TEXT NOT NULL REFERENCES source_units(unit_id),
        locale TEXT NOT NULL,
        basis TEXT NOT NULL CHECK(length(basis)=64),
        basis_json TEXT NOT NULL,
        selection_id TEXT NOT NULL REFERENCES translation_selections(event_id),
        revision_id TEXT NOT NULL REFERENCES translation_revisions(revision_id),
        source_revision_id TEXT NOT NULL REFERENCES source_revisions(revision_id),
        actor TEXT NOT NULL,
        kind TEXT NOT NULL CHECK(kind IN ('approve','request-changes')),
        reason TEXT NOT NULL,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE review_fallbacks (
        fallback_id TEXT PRIMARY KEY NOT NULL,
        action_id TEXT NOT NULL UNIQUE,
        project_id TEXT NOT NULL,
        unit_id TEXT NOT NULL REFERENCES source_units(unit_id),
        locale TEXT NOT NULL,
        source_revision_id TEXT NOT NULL REFERENCES source_revisions(revision_id),
        kind TEXT NOT NULL CHECK(kind IN ('allow','withdraw')),
        previous_fallback_id TEXT REFERENCES review_fallbacks(fallback_id),
        policy_version TEXT NOT NULL,
        actor TEXT NOT NULL,
        reason TEXT NOT NULL,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE review_finding_decisions (
        decision_id TEXT PRIMARY KEY NOT NULL,
        action_id TEXT NOT NULL UNIQUE,
        project_id TEXT NOT NULL,
        unit_id TEXT NOT NULL REFERENCES source_units(unit_id),
        locale TEXT NOT NULL,
        basis TEXT NOT NULL CHECK(length(basis)=64),
        run_id TEXT NOT NULL REFERENCES review_checks(run_id),
        issue_id TEXT NOT NULL CHECK(length(issue_id)=64),
        previous_decision_id TEXT REFERENCES review_finding_decisions(decision_id),
        request_json TEXT NOT NULL,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE review_waivers (
        waiver_id TEXT PRIMARY KEY NOT NULL,
        action_id TEXT NOT NULL UNIQUE,
        project_id TEXT NOT NULL,
        unit_id TEXT NOT NULL REFERENCES source_units(unit_id),
        locale TEXT NOT NULL,
        basis TEXT NOT NULL CHECK(length(basis)=64),
        issue_id TEXT NOT NULL,
        kind TEXT NOT NULL CHECK(kind IN ('grant','revoke')),
        previous_waiver_id TEXT REFERENCES review_waivers(waiver_id),
        policy_version TEXT NOT NULL,
        actor TEXT NOT NULL,
        reason TEXT NOT NULL,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE source_files (
        artifact_id TEXT PRIMARY KEY NOT NULL, set_id TEXT NOT NULL REFERENCES source_sets(set_id),
        logical_path TEXT NOT NULL, role TEXT NOT NULL,
        bytes BLOB NOT NULL CHECK(length(bytes)<=1048576), digest TEXT NOT NULL CHECK(length(digest)=64),
        UNIQUE(set_id,logical_path), UNIQUE(set_id,artifact_id));
