CREATE TABLE source_snapshot_mapping_bases (
        snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id),
        base_snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id),
        mapping_revision INTEGER NOT NULL CHECK(mapping_revision>=0),
        PRIMARY KEY(snapshot_id,base_snapshot_id));
CREATE TABLE source_snapshots (
        snapshot_id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL, set_id TEXT NOT NULL,
        attempt_id TEXT NOT NULL REFERENCES execution_attempts(attempt_id), result_id TEXT NOT NULL REFERENCES execution_results(result_id),
        source_language TEXT NOT NULL, identity_policy TEXT NOT NULL,
        FOREIGN KEY(set_id,project_id) REFERENCES source_sets(set_id,project_id));
INSERT INTO "source_snapshots" VALUES('e55a0d0b-14d2-4cf1-a6f5-c316a60b801b','9f32dc2b-b253-4ecc-a410-8bd78d9b8e29','f01411a1-6ebc-4ffa-a605-fdfaa37d1873','dac039c8-e0a2-4194-aeb7-1bd47237ba8c','895992c3-fa84-44e9-8d40-9719bd76c0ca','en','9ebeb16add489f62c5603136e79ba48ca10a9d827e321de2374d988b537d548b');
CREATE TABLE source_unit_mappings (
        snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id),
        local_unit_id TEXT NOT NULL, local_revision_id TEXT NOT NULL,
        unit_id TEXT NOT NULL REFERENCES source_units(unit_id), revision_id TEXT NOT NULL,
        basis_digest TEXT NOT NULL CHECK(length(basis_digest)=64),
        PRIMARY KEY(snapshot_id,local_unit_id), UNIQUE(snapshot_id,unit_id),
        FOREIGN KEY(unit_id,revision_id) REFERENCES source_revisions(unit_id,revision_id));
INSERT INTO "source_unit_mappings" VALUES('e55a0d0b-14d2-4cf1-a6f5-c316a60b801b','unit-0','source-0','b92f7f49-b6c3-4353-b2ff-c2f18fa4b9a5','54218fde-3681-4422-942b-be2244f5c1ca','c2794aaa5eb6f878e9d63847704744f3b2f31c0ba36cf4f06e52c92c9df56f22');
INSERT INTO "source_unit_mappings" VALUES('e55a0d0b-14d2-4cf1-a6f5-c316a60b801b','unit-1','source-1','90ec847d-00c6-45d2-9d9f-c9e02033bd90','d670f7b4-ba03-49c5-aa34-34a587a91c89','39bd3849729ba89d0f00ffc74e054f803096bd3fc619e894ed893feda6e75491');
CREATE TABLE source_units (
        unit_id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL);
INSERT INTO "source_units" VALUES('b92f7f49-b6c3-4353-b2ff-c2f18fa4b9a5','9f32dc2b-b253-4ecc-a410-8bd78d9b8e29');
INSERT INTO "source_units" VALUES('90ec847d-00c6-45d2-9d9f-c9e02033bd90','9f32dc2b-b253-4ecc-a410-8bd78d9b8e29');
CREATE TABLE source_validation_history (
        checker_result_id TEXT PRIMARY KEY NOT NULL REFERENCES execution_results(result_id),
        checker_attempt_id TEXT NOT NULL REFERENCES execution_attempts(attempt_id),
        producer_result_id TEXT NOT NULL REFERENCES execution_results(result_id),
        valid INTEGER NOT NULL CHECK(valid IN (0,1)));
CREATE TABLE term_current (
        term_id TEXT NOT NULL,
        project_id TEXT NOT NULL,
        revision_id TEXT NOT NULL UNIQUE REFERENCES term_revisions(revision_id),
        PRIMARY KEY(project_id,term_id));
CREATE TABLE term_revisions (
        revision_id TEXT PRIMARY KEY NOT NULL,
        term_id TEXT NOT NULL,
        project_id TEXT NOT NULL,
        locale TEXT NOT NULL,
        source TEXT NOT NULL,
        aliases_json TEXT NOT NULL,
        target TEXT NOT NULL,
        protected INTEGER NOT NULL CHECK(protected IN (0,1)),
        scope_unit_id TEXT REFERENCES source_units(unit_id),
        reason TEXT NOT NULL,
        origin_kind TEXT NOT NULL CHECK(origin_kind IN ('manual','external')),
        capture_id TEXT REFERENCES resource_captures(capture_id),
        external_entry_id TEXT,
        previous_revision_id TEXT REFERENCES term_revisions(revision_id),
        removed INTEGER NOT NULL CHECK(removed IN (0,1)),
        action_id TEXT NOT NULL UNIQUE,
        request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
        CHECK((origin_kind='manual' AND external_entry_id IS NULL)
           OR (origin_kind='external' AND capture_id IS NOT NULL AND external_entry_id IS NOT NULL)));
CREATE TABLE translation_candidate_decisions (action_id TEXT PRIMARY KEY NOT NULL, revision_id TEXT NOT NULL REFERENCES translation_revisions(revision_id), source_snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id), request BLOB NOT NULL CHECK(length(request) BETWEEN 1 AND 1048576), request_digest TEXT NOT NULL CHECK(length(request_digest)=64), receipt BLOB NOT NULL CHECK(length(receipt) BETWEEN 1 AND 1048576), receipt_digest TEXT NOT NULL CHECK(length(receipt_digest)=64));
CREATE TABLE translation_contributors (revision_id TEXT NOT NULL REFERENCES translation_revisions(revision_id), parent_revision_id TEXT NOT NULL REFERENCES translation_revisions(revision_id), ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 3), PRIMARY KEY(revision_id,parent_revision_id), UNIQUE(revision_id,ordinal), CHECK(revision_id<>parent_revision_id));
CREATE TABLE translation_resource_baselines (
        revision_id TEXT PRIMARY KEY NOT NULL REFERENCES translation_revisions(revision_id),
        last_change_rowid INTEGER NOT NULL CHECK(last_change_rowid>=0));
INSERT INTO "translation_resource_baselines" VALUES('1dec370b-7e79-4ca5-af9f-f7f8a6b7b894',0);
CREATE TABLE translation_revisions (
            revision_id TEXT PRIMARY KEY NOT NULL,
            project_id TEXT NOT NULL,
            unit_id TEXT NOT NULL REFERENCES source_units(unit_id),
            locale TEXT NOT NULL,
            ordinal INTEGER NOT NULL CHECK(ordinal > 0),
            text TEXT NOT NULL CHECK(length(CAST(text AS BLOB)) <= 16384),
            source_snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id),
            source_revision_id TEXT NOT NULL,
            origin_kind TEXT NOT NULL CHECK(origin_kind IN ('import','manual','ai')),
            action_id TEXT NOT NULL UNIQUE,
            request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
            attempt_id TEXT REFERENCES execution_attempts(attempt_id),
            result_id TEXT REFERENCES execution_results(result_id),
            item_id TEXT,
            artifact_id TEXT,
            logical_path TEXT,
            declared_locale TEXT,
            native_key TEXT,
            file_digest TEXT, reuse_origin_json TEXT,
            UNIQUE(unit_id,locale,ordinal),
            UNIQUE(unit_id,locale,revision_id),
            FOREIGN KEY(unit_id,source_revision_id) REFERENCES source_revisions(unit_id,revision_id),
            CHECK((origin_kind='manual' AND attempt_id IS NULL AND result_id IS NULL AND item_id IS NULL AND artifact_id IS NULL AND logical_path IS NULL AND declared_locale IS NULL AND native_key IS NULL AND file_digest IS NULL)
               OR (origin_kind='import' AND attempt_id IS NOT NULL AND result_id IS NOT NULL AND item_id IS NOT NULL AND artifact_id IS NOT NULL AND logical_path IS NOT NULL AND declared_locale IS NOT NULL AND native_key IS NOT NULL AND file_digest IS NOT NULL) OR (origin_kind='ai' AND attempt_id IS NOT NULL AND result_id IS NOT NULL AND item_id IS NOT NULL AND artifact_id IS NULL AND logical_path IS NULL AND declared_locale IS NULL AND native_key IS NULL AND file_digest IS NULL)));
INSERT INTO "translation_revisions" VALUES('1dec370b-7e79-4ca5-af9f-f7f8a6b7b894','9f32dc2b-b253-4ecc-a410-8bd78d9b8e29','b92f7f49-b6c3-4353-b2ff-c2f18fa4b9a5','zh-CN',1,'已保留的人工译文','e55a0d0b-14d2-4cf1-a6f5-c316a60b801b','54218fde-3681-4422-942b-be2244f5c1ca','manual','f95da58f-cbb8-42ce-b027-384aa8a3b53c','367d521524bce27d42e102f74e17fe20d39607f9de05b818564ebdfd2d2a1253',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
CREATE TABLE translation_selections (
            event_id TEXT PRIMARY KEY NOT NULL,
            project_id TEXT NOT NULL,
            unit_id TEXT NOT NULL,
            locale TEXT NOT NULL,
            sequence INTEGER NOT NULL CHECK(sequence > 0),
            revision_id TEXT NOT NULL,
            action_id TEXT NOT NULL UNIQUE,
            request_digest TEXT NOT NULL CHECK(length(request_digest)=64),
            previous_event_id TEXT REFERENCES translation_selections(event_id),
            UNIQUE(unit_id,locale,sequence),
            FOREIGN KEY(unit_id,locale,revision_id) REFERENCES translation_revisions(unit_id,locale,revision_id));
INSERT INTO "translation_selections" VALUES('93b5c97d-b0ee-4393-aea2-4e6325dc058b','9f32dc2b-b253-4ecc-a410-8bd78d9b8e29','b92f7f49-b6c3-4353-b2ff-c2f18fa4b9a5','zh-CN',1,'1dec370b-7e79-4ca5-af9f-f7f8a6b7b894','f95da58f-cbb8-42ce-b027-384aa8a3b53c','367d521524bce27d42e102f74e17fe20d39607f9de05b818564ebdfd2d2a1253',NULL);
CREATE VIEW source_effective_occurrences AS
        SELECT o.rowid AS rowid,o.occurrence_id,o.snapshot_id,o.ordinal,o.artifact_id,
        COALESCE(b.unit_id,o.unit_id) AS unit_id,COALESCE(b.revision_id,o.revision_id) AS revision_id,
        o.namespace,o.native_key,o.comparison_key,o.key_start,o.key_end,o.value_start,o.value_end,
        o.local_unit_id,o.local_occurrence_id,o.local_revision_id,o.projection
        FROM source_occurrences o LEFT JOIN source_lineage_correction_bindings b
        ON b.occurrence_id=o.occurrence_id AND b.action_id=(
          SELECT c.action_id FROM source_lineage_corrections c
          JOIN source_lineage_correction_bindings x ON x.action_id=c.action_id
          WHERE x.occurrence_id=o.occurrence_id ORDER BY c.mapping_revision DESC LIMIT 1);
CREATE VIEW source_binding_history AS
        SELECT o.rowid AS rowid,o.occurrence_id,o.snapshot_id,o.ordinal,o.artifact_id,o.unit_id,o.revision_id,
        o.namespace,o.native_key,o.comparison_key,o.key_start,o.key_end,o.value_start,o.value_end,
        o.local_unit_id,o.local_occurrence_id,o.local_revision_id,o.projection,0 AS mapping_revision
        FROM source_occurrences o UNION ALL
        SELECT o.rowid,o.occurrence_id,o.snapshot_id,o.ordinal,o.artifact_id,b.unit_id,b.revision_id,
        o.namespace,o.native_key,o.comparison_key,o.key_start,o.key_end,o.value_start,o.value_end,
        o.local_unit_id,o.local_occurrence_id,o.local_revision_id,o.projection,c.mapping_revision
        FROM source_occurrences o JOIN source_lineage_correction_bindings b ON b.occurrence_id=o.occurrence_id
        JOIN source_lineage_corrections c ON c.action_id=b.action_id;
CREATE VIEW source_effective_lineage AS
        SELECT l.occurrence_id,CASE WHEN b.action_id IS NULL THEN l.predecessor_id ELSE b.predecessor_id END AS predecessor_id,
        COALESCE(b.relation,l.relation) AS relation
        FROM source_lineage l LEFT JOIN source_lineage_correction_bindings b
        ON b.occurrence_id=l.occurrence_id AND b.action_id=(
          SELECT c.action_id FROM source_lineage_corrections c
          JOIN source_lineage_correction_bindings x ON x.action_id=c.action_id
          WHERE x.occurrence_id=l.occurrence_id ORDER BY c.mapping_revision DESC LIMIT 1);
CREATE INDEX translation_candidate_revision ON translation_candidate_decisions (revision_id);
CREATE INDEX context_fact_scope ON context_fact_decisions (unit_id,locale,source_snapshot_id,block_index,fact_id);
CREATE INDEX context_strategy_members ON context_strategy_facts(kind,project_id,association_id,member_id);
CREATE INDEX context_strategy_locales ON context_strategy_facts(kind,project_id,locale);
CREATE INDEX review_finding_scope ON review_finding_decisions (project_id,unit_id,locale,basis,issue_id);
CREATE INDEX review_finding_history ON review_finding_decisions (project_id,unit_id,locale);
CREATE INDEX review_check_purpose_scope ON review_checks (project_id,unit_id,locale,purpose,basis);
CREATE UNIQUE INDEX review_semantic_result ON review_checks (json_extract(evidence_json,'$.origin.attemptId'),json_extract(evidence_json,'$.origin.itemId'),json_extract(evidence_json,'$.origin.resultId')) WHERE purpose='ai-semantic';
COMMIT;
